import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import test from "node:test";
import { buildAcpDiff, verifyAcpDiff } from "../../../scripts/lib/acp-contract.mjs";

const v1 = JSON.parse(await readFile("protocol/acp/v1/schema.json", "utf8"));
const v2 = JSON.parse(await readFile("protocol/acp/v2-preview/schema.json", "utf8"));
const classifications = JSON.parse(await readFile("protocol/acp/change-classifications.json", "utf8"));

await test("ACP diff covers every common definition and direct required change", () => {
  const diff = buildAcpDiff(v1, v2);
  assert.equal(diff.definitionSets.commonCount, 223);
  assert.deepEqual(diff.commonDefinitions.summary, {
    identical: 33,
    documentationOnly: 100,
    structural: 90,
    directRequiredChanged: 19,
  });
  assert.equal(verifyAcpDiff(diff, classifications), true);
});

await test("an unclassified ACP structural change fails closed", () => {
  const diff = buildAcpDiff(v1, v2);
  const incomplete = structuredClone(classifications);
  incomplete.reviewedSets.structural.namesSha256 = "0".repeat(64);
  assert.throws(() => verifyAcpDiff(diff, incomplete), /exact reviewed classification/);
});

await test("an unclassified ACP required-field change fails closed", () => {
  const diff = buildAcpDiff(v1, v2);
  const incomplete = structuredClone(classifications);
  delete incomplete.requiredChanges.ContentChunk;
  assert.throws(() => verifyAcpDiff(diff, incomplete), /complete classification/);
});
